// 测试用最小 CM6 state 模拟
let seq = 0;
class StateEffect {
  constructor(id) { this.id = id; }
  is(t) { return t === this; }
  of(v) { return { is: (t) => t === this, value: v, _e: this }; }
}
function StateEffectDefine() { const e = new StateEffect(++seq); return e; }
StateEffect.define = StateEffectDefine;

const StateField = {
  define(spec) { return { spec, __field: true, provide: spec.provide }; },
};

module.exports = { StateEffect, StateField };

module.exports.__ttLoadCount = (module.exports.__ttLoadCount || 0) + 1;
